	@ParameterizedTest
	@CsvSource({ "false,false,false", "true,false,false", "false,true,false", "true,true,false",
			"false,false,true", "true,false,true" })
	void priorNativeObjectiveIntervalCannotLeakIntoFreshPhysicalTransport(boolean recipe, boolean scalar,
			boolean unknownWork) throws Exception {
		String previous = System.getProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY);
		try {
			System.setProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, "safe-plan-lifecycle");
			LmdbOperatorFeedbackStats learned = new LmdbOperatorFeedbackStats(temporary.resolve("objective-prior"));
			RuntimeFeedbackContract contract = priorContract(learned, scalar);
			observe(learned, contract);
			observe(learned, priorContract(learned, scalar));
			try (var fixture = fixture(scalar)) {
				when(fixture.runtime.feedback()).thenReturn(learned);
				try (PackedCostSession nativeSession = priorSession(fixture);
						PackedCostSession recording = PackedCostTestSupport.recording(nativeSession)) {
					int source = fixture.priceFilteredPrefix(recording);
					PackedCostEstimate output = priorEstimate(fixture, recording);
					assertEquals(1.0d, output.plannedDoubleMetric("optimizer.lifecycleEnforced", Double.NaN));
					assertTrue(Double.isFinite(output.plannedDoubleMetric("optimizer.objectivePoint", Double.NaN)),
							"the old interval is emitted by the authentic native lifecycle producer");
					assertEquals(output.objectivePoint(),
							output.plannedDoubleMetric("optimizer.objectivePoint", Double.NaN));
					double expected = (scalar || unknownWork ? 37.0d : 33.0d) * fixture.filteredRows;
					assertTrue(output.objectivePoint() != expected, "prior and replacement prices must be distinct");
					if (unknownWork) {
						fixture.unavailableDimension = LmdbPropertyPathEstimator.PLANNED_PATH_CANDIDATE_ROWS;
					}
					when(fixture.runtime.feedback()).thenReturn(null);
					recording.appendFactor(fixture.call.rightRelationId(), fixture.restrictedContext(source), output);
					if (recipe) {
						when(fixture.runtime.feedback()).thenReturn(learned);
						try (PackedCostSession replay = feedbackAtAppend(fixture, priorSession(fixture), null)) {
							var observed = PackedCostTestSupport.replayFactorRecipe(fixture.call, recording, replay,
									output, fixture.prefixPrices);
							assertObjectiveTransport(observed.replayedFactor(), expected, unknownWork);
							assertEquals(expected, observed.materializedFactor().getCostEstimate(), 0.0d);
							for (String name : new String[] { "optimizer.objectiveLower", "optimizer.objectivePoint",
									"optimizer.objectiveUpper" }) {
								assertEquals(unknownWork,
										observed.materializedFactor().getDoubleMetricsPlanned().containsKey(name));
								if (unknownWork) {
									assertEquals(expected, observed.materializedFactor().getDoubleMetricPlanned(name),
											0.0d);
								}
							}
						}
					} else {
						assertObjectiveTransport(output, expected, unknownWork);
					}
				}
			}
		} finally {
			if (previous == null) {
				System.clearProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY);
			} else {
				System.setProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, previous);
			}
		}
	}

	private static void assertObjectiveTransport(PackedCostEstimate output, double expected, boolean explicitInterval) {
		for (String name : new String[] { "optimizer.objectiveLower", "optimizer.objectivePoint",
				"optimizer.objectiveUpper" }) {
			assertEquals(explicitInterval, output.plannedDoubleMetrics().containsKey(name),
					"an absent new interval must retire the prior producer's named objective transport");
			if (explicitInterval) {
				assertEquals(expected, output.plannedDoubleMetric(name, Double.NaN), 0.0d);
			} else {
				assertTrue(Double.isNaN(output.plannedDoubleMetric(name, Double.NaN)));
			}
		}
		assertEquals(expected, output.workRows(), 0.0d,
				"physical work must use the replacement's actual invocation domain");
		assertEquals(expected, output.objectiveLower(), 0.0d);
		assertEquals(expected, output.objectivePoint(), 0.0d);
		assertEquals(expected, output.objectiveUpper(), 0.0d);
	}

	private static LmdbPhysicalFallbackFrameAuthorityTest.Fixture fixture(boolean scalar) throws Exception {
		return new LmdbPhysicalFallbackFrameAuthorityTest.Fixture(
				LmdbPhysicalFallbackFrameAuthorityTest.Endpoint.END, 0L, scalar, 1);
	}

	private static RuntimeFeedbackContract priorContract(LmdbOperatorFeedbackStats feedback, boolean scalar)
			throws Exception {
		try (var fixture = fixture(scalar)) {
			when(fixture.runtime.feedback()).thenReturn(feedback);
			try (PackedCostSession session = priorSession(fixture)) {
				PackedCostEstimate output = priorEstimate(fixture, session);
				RuntimeFeedbackContract result = output.runtimeFeedbackContract();
				assertNotNull(result);
				assertTrue(result.admits(RuntimeFeedbackContract.ADMIT_PHYSICAL));
				assertTrue(result.admits(RuntimeFeedbackContract.ADMIT_LIFECYCLE));
				return result;
			}
		}
	}

	private static PackedCostEstimate priorEstimate(LmdbPhysicalFallbackFrameAuthorityTest.Fixture fixture,
			PackedCostSession session) {
		PackedCostEstimate output = fixture.pricePath(session);
		PackedCostContext candidate = PackedCostTestSupport.prefixContext(new int[0], 0, 1.0d,
				output.evidenceStateId());
		// Establish the actual logical candidate before selecting its native physical implementation.
		session.refineIntermediateJoin(candidate, output);
		PackedCostTestSupport.refineDependentPhysicalJoin(session, candidate, output);
		return output;
	}

	private static PackedCostSession priorSession(LmdbPhysicalFallbackFrameAuthorityTest.Fixture fixture) {
		PackedCostSession scalar = PackedCostSession.scalar(fixture.model, fixture.call.query());
		PackedCostSession declaredPrior = new PackedCostSession() {
			@Override
			public void estimateLeaf(int relation, PackedCostContext context, PackedCostEstimate output) {
				scalar.estimateLeaf(relation, context, output);
				if (relation == fixture.call.rightRelationId()) {
					// Controlled upstream implementation declaration, followed by the real native evidence/feedback
					// APIs.
					output.setInclusivePhysicalCost(20.0d, 2.0d, 4.0d, 0.0d, 0.0d, 0.0d, 7.0d, 101.0d, 0.0d, 13.0d);
					output.setInvocations(1.0d);
					output.putPlannedDoubleMetric("optimizer.frontierLeo.source_rows_scanned_extra.raw", 73.0d);
					output.putPlannedStringMetric("optimizer.frontierLeo.unrecognized.note",
							"independent-provider-note");
				}
			}

			@Override
			public void appendFactor(int relation, PackedCostContext context, PackedCostEstimate output) {
				scalar.appendFactor(relation, context, output);
			}

			@Override
			public void refineOperator(int relation, PackedCostContext context, PackedCostEstimate output) {
				scalar.refineOperator(relation, context, output);
			}

			@Override
			public void close() {
				scalar.close();
			}
		};
		return new LmdbFrontierStatisticsCostSession(declaredPrior, fixture.model, fixture.view,
				fixture.call.query(), fixture.runtime, true);
	}

	private static PackedCostSession feedbackAtAppend(LmdbPhysicalFallbackFrameAuthorityTest.Fixture fixture,
			PackedCostSession delegate, LmdbOperatorFeedbackStats current) {
		return new PackedCostSession() {
			@Override
			public void estimateLeaf(int relation, PackedCostContext context, PackedCostEstimate output) {
				delegate.estimateLeaf(relation, context, output);
			}

			@Override
			public void appendFactor(int relation, PackedCostContext context, PackedCostEstimate output) {
				when(fixture.runtime.feedback()).thenReturn(current);
				delegate.appendFactor(relation, context, output);
			}

			@Override
			public void refineOperator(int relation, PackedCostContext context, PackedCostEstimate output) {
				delegate.refineOperator(relation, context, output);
			}

			@Override
			public void refineIntermediateJoin(PackedCostContext context, PackedCostEstimate output) {
				delegate.refineIntermediateJoin(context, output);
			}

			@Override
			public double objectiveScore(PackedCostEstimate output) {
				return delegate.objectiveScore(output);
			}

			@Override
			public FrontierEvidenceBundle detachEvidence(int[] ids) {
				return delegate.detachEvidence(ids);
			}

			@Override
			public void close() {
				delegate.close();
			}
		};
	}

	private static void observe(LmdbOperatorFeedbackStats feedback, RuntimeFeedbackContract contract) {
		for (int index = 0; index < 32; index++) {
			RuntimeFeedbackTarget target = feedback.resolveRuntimeFeedbackTarget(contract);
			assertTrue(target.active(), "native feedback must resolve the real producer's physical/lifecycle lease");
			target.open();
			target.close(101L, 500.0d, 40L, 2L, 4L, 0L, 0L, 0L, 7L, 0L,
					EvaluationStatistics.TerminationClassification.EXHAUSTED);
			target.recordActualPhysicalImplementation(contract.physicalImplementationId());
			feedback.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
		}
	}

	private static Map<String, Double> logicalDoubles(PackedCostEstimate output) {
		return output.plannedDoubleMetrics()
				.entrySet()
				.stream()
				.filter(entry -> entry.getKey().startsWith("optimizer.frontierLeo.output_rows.")
						|| entry.getKey().startsWith("optimizer.frontierLeo.semi_anti_hit_rate."))
				.collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
	}

	private static Map<String, String> logicalStrings(PackedCostEstimate output) {
		return output.plannedStringMetrics()
				.entrySet()
				.stream()
				.filter(entry -> entry.getKey().startsWith("optimizer.frontierLeo.output_rows.")
						|| entry.getKey().startsWith("optimizer.frontierLeo.semi_anti_hit_rate."))
				.collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
	}
